 async function sendBroadcast(){if(broadcastBusy||!broadcastPending)return;broadcastBusy=true;$('supportBroadcastSend').disabled=true;try{await call({action:'send',...broadcastPending},'supportBroadcast');broadcastPending=null;$('supportBroadcastText').value='';updatePreviews();$('supportBroadcastConfirm').hidden=true;note('تمت جدولة الإعلان. يستمر إرساله حتى إذا أغلقت النافذة.');await broadcasts();}catch(e){note((e.message||'تعذر الإرسال')+' — يمكنك إعادة المحاولة دون تكرار الإعلان.');}finally{broadcastBusy=false;$('supportBroadcastSend').disabled=false;}}
 function openRequested(){if(!identity||new URLSearchParams(location.search).get('support')!=='chat')return;const url=new URL(location.href);url.searchParams.delete('support');history.replaceState(history.state,'',url);queueMicrotask(()=>open().catch(e=>note(e.message)));}
 function setup(){announcementEntry();if($('supportChatDialog'))return;const d=document.createElement('dialog');d.id='supportChatDialog';d.dir='rtl';d.setAttribute('aria-labelledby','supportChatTitle');d.innerHTML='<header><h2 id="supportChatTitle">محادثات الدعم</h2><button id="supportChatClose" type="button" aria-label="إغلاق">×</button></header><button id="supportChatRefreshList" class="btn ghost" type="button" hidden>تحديث حالة القراءة</button><div id="supportChatList"></div><button id="supportChatMoreThreads" class="btn ghost" hidden>محادثات أقدم</button><section id="supportChatPane" hidden><p id="supportChatState"></p><button id="supportChatResolve" class="btn ghost" hidden>إغلاق طلب الدعم</button><button id="supportChatOlder" class="btn ghost" hidden>رسائل أقدم</button><div id="supportChatMessages" role="log" aria-live="polite"></div><div id="supportChatAttachment" hidden><img id="supportChatPreview" alt="معاينة الصورة"><button id="supportChatRemoveImage" type="button">إزالة الصورة</button></div><label for="supportChatText">رسالتك</label><textarea id="supportChatText" maxlength="2000" rows="3" placeholder="اشرح المشكلة…"></textarea><div class="supportChatActions"><label class="btn ghost">إرفاق صورة<input id="supportChatFile" type="file" accept="image/jpeg,image/png,image/webp" hidden></label><button class="btn" id="supportChatSend" type="button">إرسال</button></div></section><p id="supportChatStatus" role="status"></p>';document.body.append(d);const panel=document.createElement('details');panel.id='supportBroadcastPanel';panel.hidden=true;panel.innerHTML='<summary>إرسال إعلان للجميع</summary><p>يصل إلى حسابات التدريسيين المعتمدة داخل الشات، وإشعار هاتف لمن فعّل الإشعارات.</p><label for="supportBroadcastText">نص الإعلان</label><textarea id="supportBroadcastText" rows="3" maxlength="2000" placeholder="اكتب الإعلان…"></textarea><button id="supportBroadcastReview" class="btn" type="button">معاينة الإعلان</button><section id="supportBroadcastConfirm" hidden><strong>إرسال هذا الإعلان لجميع التدريسيين؟</strong><p id="supportBroadcastPreview"></p><button id="supportBroadcastSend" class="btn" type="button">تأكيد الإرسال للجميع</button><button id="supportBroadcastCancel" class="btn ghost" type="button">رجوع</button></section><button id="supportBroadcastRefresh" class="btn ghost" type="button">تحديث حالة الإعلانات</button><div id="supportBroadcastHistory"></div>';d.querySelector('header').after(panel);$('supportBroadcastReview').onclick=previewBroadcast;$('supportBroadcastSend').onclick=sendBroadcast;$('supportBroadcastCancel').onclick=()=>{$('supportBroadcastConfirm').hidden=true;};$('supportBroadcastRefresh').onclick=()=>broadcasts().catch(e=>note(e.message));
  const announcements=document.createElement('dialog');announcements.id='announcementsDialog';announcements.dir='rtl';announcements.setAttribute('aria-labelledby','announcementsTitle');announcements.innerHTML='<header><h2 id="announcementsTitle">الإعلانات</h2><button id="announcementsClose" aria-label="إغلاق" type="button">×</button></header><button id="announcementsCompose" class="btn" type="button" hidden>إرسال إعلان للجميع</button><div id="announcementsList"></div><button id="announcementsOlder" class="btn ghost" type="button" hidden>إعلانات أقدم</button><section id="announcementDetail" hidden><h3 id="announcementDetailTitle"></h3><div id="announcementBody"></div></section><p id="announcementStatus" role="status"></p>';document.body.append(announcements);$('announcementsClose').onclick=()=>announcements.close();$('announcementsOlder').onclick=()=>mailboxRefresh(true).catch(e=>$('announcementStatus').textContent=e.message);$('announcementsCompose').onclick=async()=>{announcements.close();await open();$('supportBroadcastPanel').open=true;};
  addFormatting('supportChatText');addFormatting('supportBroadcastText');
  $('supportChatRefreshList').onclick=()=>list().catch(e=>note(e.message));
  $('supportChatClose').onclick=close;d.addEventListener('cancel',e=>{e.preventDefault();close();});$('supportChatSend').onclick=send;$('supportChatOlder').onclick=()=>refresh(true).catch(e=>note(e.message));$('supportChatMoreThreads').onclick=()=>list(true).catch(e=>note(e.message));$('supportChatResolve').onclick=()=>call({action:'close',threadId:thread}).then(()=>refresh()).catch(e=>note(e.message));$('supportChatFile').onchange=e=>{void attach(e.target.files[0]).catch(e=>note(e.message));e.target.value='';};$('supportChatText').oninput=()=>{pending=null;saveDraft();};$('supportChatRemoveImage').onclick=()=>{if(busy)return;image='';pending=null;showImage();saveDraft();};
 }
 const prior=init;init=function(...a){const result=prior.apply(this,a);setup();auth?.onAuthStateChanged(()=>refreshIdentity());refreshIdentity();return result;};const render=renderAll;renderAll=function(...a){const r=render.apply(this,a);setup();refreshIdentity();return r;};window.addEventListener('online',()=>{if(thread)void refresh().catch(e=>note(e.message));});document.addEventListener('visibilitychange',()=>{if(!document.hidden&&thread)void refresh().catch(e=>note(e.message));});window.HathirSupportChat=Object.freeze({open:()=>open().catch(e=>note(e.message)),announcements:messageId=>openAnnouncements(messageId).catch(e=>{$('announcementStatus').textContent=e.message;})});
